import React, { useState, useEffect } from "react";
import {
  Container,
  Row,
  Col,
  Card,
  Table,
  Button,
  Form,
  InputGroup,
  Modal,
} from "react-bootstrap";
import axios from "axios";

const STUDENT = () => {
  const [tasks, setTasks] = useState([]);
  const [filterStatus, setFilterStatus] = useState("All");
  const [search, setSearch] = useState("");
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  useEffect(() => {
    fetchTasks();
  }, []);

  // ✅ Fetch tasks for this student
  const fetchTasks = () => {
    axios
      .get("https://localhost:7013/api/Task/Student/1") // pass studentId dynamically
      .then((res) => {
        setTasks(res.data || []);
      })
      .catch((err) => console.error(err));
  };

  // ✅ Update task status
  const handleStatusChange = (taskId, newStatus) => {
    axios
      .put(`https://localhost:7013/api/Task/UpdateStatus/${taskId}`, {
        status: newStatus,
      })
      .then(() => {
        alert("Task status updated ✅");
        fetchTasks();
      })
      .catch((err) => console.error(err));
  };

  // ✅ Logout function
  const handleLogout = () => {
    // Clear any stored authentication data
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    sessionStorage.removeItem("token");
    sessionStorage.removeItem("user");
    
    // Redirect to login page
    window.location.href = "/login"; // Change this to your actual login route
    
    // Alternatively, you can use:
    // window.location.reload(); // if you want to refresh and show login
    // or use React Router: navigate('/login');
  };

  // ✅ Show logout confirmation modal
  const confirmLogout = () => {
    setShowLogoutModal(true);
  };

  // ✅ Filter tasks
  const filteredTasks = tasks.filter((task) => {
    return (
      (filterStatus === "All" || task.status === filterStatus) &&
      (task.taskName.toLowerCase().includes(search.toLowerCase()) ||
        task.moduleName.toLowerCase().includes(search.toLowerCase()))
    );
  });

  return (
    <Container fluid className="p-4">
      {/* ✅ Page Title and Logout Button */}
      <Row className="mb-2">
        <Col>
          <h1 className="text-center fw-bold display-4 text-info">
            Student Dashboard
          </h1>
        </Col>
        <Col xs="auto" className="text-end">
          <Button 
            variant="outline-danger" 
            size="sm"
            onClick={confirmLogout}
          >
            Logout
          </Button>
        </Col>
      </Row>

      <Row>
        <Col>
          {/* ✅ Task Filters */}
          <Card className="shadow mb-4">
            <Card.Header>
              <h3>Your Tasks</h3>
            </Card.Header>
            <Card.Body>
              <Row className="mb-3">
                <Col md={4}>
                  <InputGroup>
                    <Form.Control
                      placeholder="Search by task/module"
                      value={search}
                      onChange={(e) => setSearch(e.target.value)}
                    />
                  </InputGroup>
                </Col>
                <Col md={3}>
                  <Form.Select
                    value={filterStatus}
                    onChange={(e) => setFilterStatus(e.target.value)}
                  >
                    <option value="All">All</option>
                    <option value="Not Started">Not Started</option>
                    <option value="In Progress">In Progress</option>
                    <option value="Complete">Complete</option>
                  </Form.Select>
                </Col>
              </Row>

              {/* ✅ Tasks Table */}
              <Table striped bordered hover>
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Task Name</th>
                    <th>Due Date</th>
                    <th>Module</th>
                    <th>Status</th>
                    <th>Update</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredTasks.length > 0 ? (
                    filteredTasks.map((t, i) => (
                      <tr key={i}>
                        <td>{t.taskId}</td>
                        <td>{t.taskName}</td>
                        <td>{new Date(t.dueDate).toLocaleDateString()}</td>
                        <td>{t.moduleName}</td>
                        <td>{t.status}</td>
                        <td>
                          <Form.Select
                            size="sm"
                            value={t.status}
                            onChange={(e) =>
                              handleStatusChange(t.taskId, e.target.value)
                            }
                          >
                            <option value="Not Started">Not Started</option>
                            <option value="In Progress">In Progress</option>
                            <option value="Complete">Complete</option>
                          </Form.Select>
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="6" className="text-center">
                        No tasks found
                      </td>
                    </tr>
                  )}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* ✅ Logout Confirmation Modal */}
      <Modal show={showLogoutModal} onHide={() => setShowLogoutModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Confirm Logout</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          Are you sure you want to logout?
        </Modal.Body>
        <Modal.Footer>
          <Button 
            variant="secondary" 
            onClick={() => setShowLogoutModal(false)}
          >
            Cancel
          </Button>
          <Button 
            variant="danger" 
            onClick={handleLogout}
          >
            Logout
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
};

export default STUDENT;
